#include "civ5/runtime/bnw_happiness_minors.hpp"
#include "civ5/runtime/file_identity.hpp"
#include "civ5/ui/selected_bnw_preview_host.hpp"
#include <iostream>
using namespace civ5;using namespace civ5::runtime;
namespace {
void check(bool ok,const char *why){if(!ok)throw std::runtime_error(why);}template<class F>void rejects(F f,const char *why){try{f();}catch(const std::exception&){return;}throw std::runtime_error(why);}
auto &named(auto &rows,std::string_view name){for(auto &r:rows)if(r.name&&name==r.name)return r;throw std::runtime_error("Missing minor happiness fixture field");}
const BnwMinorHappinessTerm &term(const BnwMinorHappinessQuote &q,std::int64_t minor){for(const auto &t:q.minors)if(t.minor==minor)return t;throw std::runtime_error("Missing minor happiness term");}
}
int main(int argc,char **argv){
 check(argc==3||argc==4,"Expected selected save, installation and optional SDK source root");
 if(argc==4){const auto sdk=std::filesystem::path(argv[3]);check(identify_file(sdk/"CvGameCoreDLL_Expansion2/CvMinorCivAI.cpp").sha256=="83995c0c02dd4f3d7805201660c12c00a3ebfaed85e68c0b01744a1803d91055","Minor source SDK pin differs");check(identify_file(sdk/"CvGameCoreDLLUtil/include/CvEnums.h").sha256=="6781f34a6a6a9fac1cbaad3a3477afabf540669af9f860f57ad54b967c22da9b","Native mercantile enum SDK pin differs");}
 auto selected=ui::bootstrap_selected_bnw_preview(argv[1],argv[2],0);check(static_cast<bool>(selected.preview),"Minor selected bootstrap failed");auto &host=*selected.preview.host;const auto p=host.active_player_id();const auto &source=host.session().state();const auto stock=BnwMinorHappinessRules::load(host.database());const auto baseline=quote_bnw_happiness_from_minors(source,stock,host.identity(),p);
 auto db=host.database().clone_gameplay();db->apply_sql("UPDATE Defines SET Value=2 WHERE Name LIKE 'FRIENDS_HAPPINESS_FLAT_BONUS_AMOUNT_%'; UPDATE Defines SET Value=5 WHERE Name LIKE 'ALLIES_HAPPINESS_FLAT_BONUS_AMOUNT_%'; UPDATE Defines SET Value=1 WHERE Name LIKE 'FRIENDS_HAPPINESS_PER_LUXURY_BONUS_AMOUNT_%'; UPDATE Defines SET Value=3 WHERE Name LIKE 'ALLIES_HAPPINESS_PER_LUXURY_BONUS_AMOUNT_%'; UPDATE Defines SET Value=30 WHERE Name='FRIENDSHIP_THRESHOLD_FRIENDS'; UPDATE Defines SET Value=-60 WHERE Name='MINOR_FRIENDSHIP_AT_WAR';");
 const auto rules=BnwMinorHappinessRules::load(*db);auto identity=host.identity();identity.rules_sha256=rules.rules_sha256();auto state=source;
 std::string mercantile;for(const auto &[type,trait]:rules.minor_traits())if(trait==3){mercantile=type;break;}check(!mercantile.empty(),"Mercantile fixture rule absent");
 constexpr std::int64_t minor=22;for(std::int64_t m=22;m<63;++m){state.setup.players.at(m).alive=m==minor;named(state.world.all_players->players.at(m).core.fields,"m_bAlive").values={m==minor};}
 state.world.pregame->archive.string_arrays.at("minor_civ_types").at(minor)=mercantile;
 auto &ai=named(state.world.all_players->players.at(minor).planning.blocks,"minor_civ_ai");named(ai.fields,"m_eAlly").value=p;state.treasury.players.at(minor).ally=p;auto &influence=named(ai.arrays,"m_aiFriendshipWithMajorTimes100");influence.values.at(p)=3000;
 const auto team=state.setup.players.at(p).team,mteam=state.setup.players.at(minor).team;auto &war=named(state.world.teams->teams.at(team).arrays,"at_war");war.values.at(mteam)=0;state.player_research.teams.at(team).at_war.erase(mteam);
 const auto types=db->cache_info_types();const auto *gold=types.find("RESOURCE_GOLD"),*silver=types.find("RESOURCE_SILVER");check(gold&&silver,"Luxury fixture types absent");
 auto &core=state.world.all_players->players.at(p).core;for(const char *name:{"m_paiNumResourceUsed","m_paiNumResourceTotal","m_paiResourceExport","m_paiResourceImport","m_paiResourceFromMinors","m_paiResourcesSiphoned"}){auto &f=named(core.fields,name);f.hashes.clear();f.values.clear();f.wire_count=0;}
 auto &total=named(core.fields,"m_paiNumResourceTotal");total.hashes={gold->hash,silver->hash};total.values={1,1};total.wire_count=2;named(core.fields,"m_iMinorResourceBonusCount").values={0};
 saves::LeagueObservation league;league.members.push_back({});league.members.back().player=p;saves::ResolutionObservation ban;ban.effects.flags={{"no_resource_happiness",1}};ban.proposer_decision.vote.choice=gold->id;league.active_resolutions.push_back(ban);state.world.leagues.leagues={league};
 auto q=quote_bnw_happiness_from_minors(state,rules,identity,p);check(q.total==15&&term(q,minor).flat==7&&term(q,minor).per_luxury==8&&term(q,minor).luxuries==2&&term(q,minor).allied&&term(q,minor).friends,"Additive ally/friend or banned available luxury differs");
 named(core.fields,"m_iExtraHappinessPerLuxury").values={INT32_MAX};check(quote_bnw_happiness_from_minors(state,rules,identity,p).total==15,"Minor availability re-evaluated unrelated resource happiness overflow");
 influence.values.at(p)=2999;q=quote_bnw_happiness_from_minors(state,rules,identity,p);check(q.total==11&&!term(q,minor).friends,"Influence must truncate before friend threshold");
 named(ai.fields,"m_eAlly").value=-1;state.treasury.players.at(minor).ally=-1;influence.values.at(p)=3000;check(quote_bnw_happiness_from_minors(state,rules,identity,p).total==4,"Influence incorrectly inferred ally");
 war.values.at(mteam)=1;state.player_research.teams.at(team).at_war.insert(mteam);q=quote_bnw_happiness_from_minors(state,rules,identity,p);check(q.total==0&&term(q,minor).effective_influence==-60,"War did not override base influence");
 named(ai.fields,"m_eAlly").value=p;state.treasury.players.at(minor).ally=p;q=quote_bnw_happiness_from_minors(state,rules,identity,p);check(q.total==11&&term(q,minor).allied&&!term(q,minor).friends,"Direct ally cache was incorrectly erased by war query");
 war.values.at(mteam)=0;state.player_research.teams.at(team).at_war.erase(mteam);auto eradb=db->clone_gameplay();eradb->apply_sql("UPDATE Defines SET Value=17 WHERE Name='FRIENDS_HAPPINESS_FLAT_BONUS_AMOUNT_MEDIEVAL'; UPDATE Defines SET Value=29 WHERE Name='FRIENDS_HAPPINESS_FLAT_BONUS_AMOUNT_INDUSTRIAL';");const auto eras=BnwMinorHappinessRules::load(*eradb);auto eraid=identity;eraid.rules_sha256=eras.rules_sha256();const auto *medieval=types.find("ERA_MEDIEVAL"),*industrial=types.find("ERA_INDUSTRIAL");check(medieval&&industrial,"Era fixture types absent");
 named(state.world.teams->teams.at(team).fields,"era").value=medieval->id;state.maintenance.team_eras.at(team)=medieval->id;check(quote_bnw_happiness_from_minors(state,eras,eraid,p).total==30,"Medieval bonus branch differs");named(state.world.teams->teams.at(team).fields,"era").value=industrial->id;state.maintenance.team_eras.at(team)=industrial->id;check(quote_bnw_happiness_from_minors(state,eras,eraid,p).total==42,"Industrial bonus branch differs");
 auto wrong=state;wrong.treasury.players.at(minor).ally=-1;rejects([&]{quote_bnw_happiness_from_minors(wrong,eras,eraid,p);},"Stale owned ally accepted");wrong=state;wrong.maintenance.team_eras.at(team)=0;rejects([&]{quote_bnw_happiness_from_minors(wrong,eras,eraid,p);},"Stale current era accepted");wrong=state;named(named(wrong.world.all_players->players.at(minor).planning.blocks,"minor_civ_ai").arrays,"m_aiFriendshipWithMajorTimes100").values.pop_back();rejects([&]{quote_bnw_happiness_from_minors(wrong,eras,eraid,p);},"Incomplete influence span accepted");wrong=state;named(wrong.world.teams->teams.at(team).arrays,"at_war").values.at(mteam)=1;rejects([&]{quote_bnw_happiness_from_minors(wrong,eras,eraid,p);},"Stale live war relationship accepted");
 auto overflowdb=db->clone_gameplay();overflowdb->apply_sql("UPDATE Defines SET Value=2147483647 WHERE Name LIKE 'ALLIES_HAPPINESS_PER_LUXURY_BONUS_AMOUNT_%';");const auto overflow=BnwMinorHappinessRules::load(*overflowdb);auto overflowid=identity;overflowid.rules_sha256=overflow.rules_sha256();rejects([&]{quote_bnw_happiness_from_minors(state,overflow,overflowid,p);},"Native luxury multiplication overflow accepted");
 check(quote_bnw_happiness_from_minors(state,rules,identity,minor).total==0,"Minor player received major-only bonus");check(quote_bnw_happiness_from_minors(source,stock,host.identity(),p).total==baseline.total&&!host.session().readiness().can_continue(),"Minor quote mutated source/readiness");
 std::cout<<"PASS selected minor happiness="<<baseline.total<<"; ally/friend/war/luxury availability/era/stale/overflow fixtures\n";
}
